<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Empty from '../components/common/Empty.vue';import Notice from '../components/common/Notice.vue';import LiveFilterSeries from '../components/LiveFilterSeries.vue';import {filterApi} from '../api/filter';import {useTask} from '../hooks/useTask';import {FILTER_STATE} from '../constants/enums';const p=defineProps<{studies:any[];profiles:any[];user:any}>();const list=ref<any[]>([]),selected=ref<number>(0),detail=ref<any>(null),listError=ref(''),task=useTask(),studyId=ref(0),profileId=ref(0),sessionName=ref('实时滤波 '+new Date().toLocaleTimeString()),initial=ref(''),appendText=ref(''),correctPosition=ref(1),correctToken=ref(''),autoRefresh=ref(true),newStudy=computed(()=>p.studies.find(s=>s.id===(studyId.value||p.studies[0]?.id))),newProfiles=computed(()=>p.profiles.filter(m=>m.study_id===newStudy.value?.id)),canWrite=computed(()=>p.user.role!=='viewer');let pollTimer:ReturnType<typeof setInterval>|null=null,listTimer:ReturnType<typeof setInterval>|null=null;watch(newStudy,()=>{profileId.value=0});async function select(id:number){selected.value=id;detail.value=await filterApi.session(id).catch(e=>{listError.value=e.message;return null})}async function reloadList(){try{list.value=await filterApi.sessions();listError.value='';if(!selected.value&&list.value.length)await select(list.value[0].id)}catch(e){listError.value=e.message}}async function reloadDetail(){if(!selected.value)return;try{detail.value=await filterApi.session(selected.value)}catch(e){listError.value=e.message}}async function create(){await task.act(async()=>{const r=await filterApi.create({study_id:newStudy.value.id,profile_id:profileId.value||newProfiles.value[0]?.id,name:sessionName.value,initial_tokens:initial.value.trim().split(/\s+/).filter(Boolean)});await reloadList();await select(r.session_id);sessionName.value='实时滤波 '+new Date().toLocaleTimeString();initial.value=''},'已建立固定模型实时滤波会话，正在递推前缀')}async function append(){const tokens=appendText.value.trim().split(/\s+/).filter(Boolean);if(!tokens.length)return;const revision=detail.value.revision;await task.act(async()=>{await filterApi.append(selected.value,tokens,revision);appendText.value='';await reloadDetail()},`已追加${tokens.length}码；仅新增前缀参与计算`)}async function correct(){const position=Number(correctPosition.value);if(!Number.isInteger(position)||position<1)return;await task.act(async()=>{await filterApi.correct(selected.value,[{position,token:correctToken.value.trim().toUpperCase()}],detail.value.revision);correctToken.value='';await reloadDetail()},`已更正第${position}位；该位置及以后失效重算，之前前缀保留`)}async function recompute(){await task.act(async()=>{await filterApi.compute(selected.value);await reloadDetail()},'已请求按当前修订重新计算过期部分')}function running(){return !!(detail.value&&detail.value.stale&&detail.value.compute_active)}function pageLabel(){if(!detail.value)return '未选择';if(!detail.value.stale)return '当前修订结果完整';if(running())return '重算中，展示上一版并标明过期';return '结果过期，可重新计算'}onMounted(async()=>{await reloadList();pollTimer=setInterval(()=>{if(autoRefresh.value&&running())reloadDetail()},1500);listTimer=setInterval(reloadList,5000)});onUnmounted(()=>{if(pollTimer)clearInterval(pollTimer);if(listTimer)clearInterval(listTimer)});</script><template><PageTitle index="03" title="观测在来，结果只回答已经发生的部分。" description="固定模型不变；逐批追加后给出仅依据当时前缀的隐态概率与累计对数似然，绝不借用未来观测。"><a class="primary" href="#results">离线段结果与联合MAP ↗</a></PageTitle><div class="filter-layout"><aside class="filter-list"><div class="section-head"><h2>实时会话</h2><span>{{list.length}}个</span></div><button v-for="s in list" :key="s.id" :class="['filter-item',{active:s.id===selected}]" @click="select(s.id)"><strong>{{s.name}}</strong><small>#{{s.id}} / 第{{s.revision}}修订 / {{s.position_count}}码 / {{FILTER_STATE[s.compute_state]||s.compute_state}}</small><em v-if="s.stale">结果过期</em><em v-else>已对齐</em></button><p v-if="!list.length">还没有会话。用右侧固定模型建立第一个。</p></aside><div class="filter-main"><form v-if="canWrite" class="input-panel" @submit.prevent="create"><small>NEW LIVE SESSION / FIXED MODEL</small><h2>固定一个模型版本，开始逐批采码</h2><label>观测研究<select :value="newStudy?.id||0" @change="studyId=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>固定模型版本<select :value="profileId||newProfiles[0]?.id||0" @change="profileId=Number(($event.target as HTMLSelectElement).value)"><option v-for="m in newProfiles" :key="m.id" :value="m.id">{{m.name}} / {{m.version}}</option></select></label><label>会话名称<input v-model="sessionName" required/></label><label>已到达的初始码（空格分隔，可留空）<textarea v-model="initial" rows="2" placeholder="A B C"/></label><button class="primary" :disabled="task.state.busy||!newProfiles.length">建立实时滤波会话 →</button></form><p v-else class="boundary-note">观察员可查看实时前缀结果；追加与更正经分析员或负责人操作。</p><Notice :error="listError"/><Notice v-bind="task.state"/><template v-if="detail"><div class="record-title"><small>LIVE FILTER / #{{detail.id}} / MODEL #{{detail.profile_id}}</small><h2>{{detail.name}}</h2><span :class="['status',detail.stale?(running()?'running':'failed'):'completed']">{{pageLabel()}}</span></div><dl class="inference-summary filter-summary"><div><dt>已接收 / 已算到的位置</dt><dd>{{detail.observed_count}}<em> / {{detail.result?.computed_through??0}}</em></dd></div><div><dt>当前观测修订 / 结果修订</dt><dd>{{detail.revision}}<em> / {{detail.result_revision??'—'}}</em></dd></div><div><dt>可复用前缀 / 续算起点</dt><dd>{{detail.valid_prefix_count}}<em> / 第{{detail.valid_prefix_count+1}}位</em></dd></div><div><dt>计算状态</dt><dd style="font-size:16px">{{FILTER_STATE[detail.compute_state]||detail.compute_state}}</dd></div></dl><p v-if="detail.stale" class="stale-banner">{{pageLabel()}}：自上一版结果以来新增{{detail.staleness.appended_positions}}码、更正{{detail.staleness.corrected_positions}}码。整页数字保持第{{detail.result?.revision??'—'}}修订的完整结果，不与新观测混合<template v-if="detail.invalidated_from">；更正使第{{detail.invalidated_from}}位及以后失效，之前{{detail.valid_prefix_count}}个前缀不重算</template>。</p><p v-if="detail.result&&detail.result.blocked" class="notice error">第{{detail.result.failure_position}}位在当前固定模型下所有路径概率为0：{{detail.result.failure_message}}此前{{detail.result.computed_through}}个前缀结果保留。</p><template v-if="detail.result"><LiveFilterSeries :result="detail.result" :stale="detail.stale"/><div class="filter-actions"><form v-if="canWrite" class="filter-form" @submit.prevent="append"><label>追加新观测码（空格分隔）<input v-model="appendText" placeholder="A B C D"/></label><button class="primary" :disabled="task.state.busy">追加一批 →</button></form><form v-if="canWrite" class="filter-form" @submit.prevent="correct"><label>更正第 <input v-model.number="correctPosition" type="number" min="1" :max="detail.observed_count" class="inline-number"/> 位的码</label><input v-model="correctToken" placeholder="A" maxlength="80"/><button :disabled="task.state.busy||!correctToken.trim()">更正该位置 →</button></form><button v-if="canWrite" @click="recompute" :disabled="task.state.busy">按当前修订重算部分 ↻</button><label class="auto-refresh"><input type="checkbox" v-model="autoRefresh"/> 自动刷新</label></div><div class="filter-meta"><span>结果指纹 {{detail.result.digest.slice(0,16)}}…</span><span>固定 {{detail.result.profile_name}} / {{detail.result.profile_version}}</span><span>本次续算自第{{detail.result.resumed_from}}位，复用{{detail.result.reused_prefix_count}}个前缀</span></div><p class="boundary-note">{{detail.result.note}}</p></template><Empty v-else title="当前修订还没有完整结果" help="追加或更正会排队递推；结果算好前不展示拼接值。"/></template><Empty v-else title="选择一个实时会话" help="左侧列出会话；也可以先用固定模型与初始观测建立。"/></div></div></template>
